 public const string Folder="TruckTugOfWar",Scene="Assets/TruckTugOfWar/Scenes/TruckTugOfWar.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<TugMatch>(Folder);Directory.CreateDirectory("Assets/"+Folder+"/Models");AssetDatabase.Refresh();m.teamA=m.teamB=4;m.option=0;m.NormalizeSetup();m.feedback.clips=(AudioClip[])LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create().Clone();m.feedback.clips[5]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Exceptional cheer.wav");var mud=SportsEventAuthoring.Mat(Folder,"Volcanic churned mud",new Color(.3f,.19f,.11f),.12f);var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckKeepaway/Materials/Rocky mud terrain.mat");if(source!=null&&source.mainTexture!=null)mud.mainTexture=source.mainTexture;var rock=SportsEventAuthoring.Mat(Folder,"Layered volcanic ledge",new Color(.2f,.18f,.2f),.08f);var contact=SportsEventAuthoring.Contact(Folder,"Mud wheel contact",.8f,.02f);var ledge=Platform();for(int side=-1;side<=1;side+=2){var g=new GameObject("Solid modeled mountain ledge "+side);g.transform.position=new Vector3(side*25,0,0);g.AddComponent<MeshFilter>().sharedMesh=ledge;g.AddComponent<MeshRenderer>().sharedMaterial=mud;var collider=g.AddComponent<MeshCollider>();collider.sharedMesh=ledge;collider.sharedMaterial=contact;var cliff=new GameObject("Installed mountains and cliff scale").transform;for(int n=0;n<8;n++){var mountain=new GameObject("Bounded installed volcanic mountain "+n).transform;mountain.SetParent(cliff,false);mountain.position=new Vector3(side*(65+n%2*24),-45,-42+n/2*28);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(mountain,"Assets/Toon Gas Station/Prefabs/Rock_Cluster_1A.prefab",new Vector3(20,55+n%3*9,22),0,true,Folder);foreach(var renderer in mountain.GetComponentsInChildren<Renderer>())renderer.sharedMaterials=Enumerable.Repeat(rock,renderer.sharedMaterials.Length).ToArray();}for(int z=-7;z<=7;z+=2){var paint=SportsEventAuthoring.Box("Readable ledge danger chevron",new Vector3(side*10.7f,.03f,z),new Vector3(.5f,.035f,.9f),SportsEventAuthoring.Mat(Folder,"Danger orange",new Color(1,.35f,.02f)));paint.transform.rotation=Quaternion.Euler(0,side*25,0);}}
 var lava=SportsEventAuthoring.Mat(Folder,"Glowing distant lava",new Color(.65f,.035f,.005f),.5f);lava.EnableKeyword("_EMISSION");lava.SetColor("_EmissionColor",new Color(1,.08f,.005f)*2.4f);var pool=SportsEventAuthoring.Box("Lava far below the mountain",new Vector3(0,-55,0),new Vector3(280,1,210),lava,contact);for(int i=0;i<7;i++){var light=new GameObject("Lava glow "+i).AddComponent<Light>();light.type=LightType.Point;light.transform.position=new Vector3((i-3)*8,-42,0);light.color=new Color(1,.12f,.015f);light.intensity=50;light.range=48;light.shadows=LightShadows.None;}var stripe=SportsEventAuthoring.Mat(Folder,"Lava cooling crust",new Color(.15f,.015f,.01f),.03f);for(int i=0;i<14;i++){var slab=SportsEventAuthoring.Box("Floating volcanic crust",new Vector3(Mathf.Sin(i*7)*58,-54.47f,Mathf.Cos(i*13)*65),new Vector3(6+i%3*2,.08f,3),stripe);slab.transform.rotation=Quaternion.Euler(0,i*43,0);}
 m.headers=new Rigidbody[2];for(int i=0;i<2;i++){var g=new GameObject("Team physical rope header "+i);g.transform.position=new Vector3(i==0?-13:13,.7f,0);var body=g.AddComponent<Rigidbody>();body.mass=5;body.useGravity=false;body.constraints=RigidbodyConstraints.FreezePositionY|RigidbodyConstraints.FreezeRotation;body.linearDamping=.2f;body.solverIterations=20;body.maxLinearVelocity=16;body.isKinematic=true;m.headers[i]=body;}
 var ropeMaterial=SportsEventAuthoring.Mat(Folder,"Braided rope gold",new Color(.73f,.49f,.18f),.16f);m.ropes=new LineRenderer[9];for(int i=0;i<9;i++){var line=new GameObject(i==0?"Single authoritative central rope":"Team tow rope "+i).AddComponent<LineRenderer>();line.sharedMaterial=ropeMaterial;line.startWidth=line.endWidth=i==0?.18f:.1f;line.numCapVertices=3;line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.On;line.receiveShadows=true;line.useWorldSpace=true;m.ropes[i]=line;}
 m.trucks=new SportsEventTruck[8];m.fragments=new SportsFragmentRig[8];m.fire=new ParticleSystem[8];var flare=SportsChaosAuthoring.Flare(Folder);for(int i=0;i<8;i++){var t=SportsEventAuthoring.Truck(m,Folder,"Mountain tug participant "+(i+1),new Vector3((i<4?-1:1)*17,.7f,(i%4-1.5f)*3.5f),i);SportsRallyAuthoring.FitTruck(t);t.motorTorque=7;t.maxSpeed=11;t.reverseSpeed=9;t.steerAngle=18;t.grip=1.55f;t.body.solverIterations=20;t.body.maxLinearVelocity=32;m.trucks[i]=t;m.fragments[i]=SportsFragmentAuthoring.Install(t,Folder);var fire=new GameObject("Bounded lava explosion "+i).AddComponent<ParticleSystem>();SportsChaosAuthoring.FixBlast(fire,flare);m.fire[i]=fire;}
 m.replay=SportsRallyAuthoring.Replay(m,m.trucks.Select(t=>t.transform).ToArray());m.replay.capacity=2500;m.broadcast=SportsEventAuthoring.Camera("Mountain tug shared broadcast");m.broadcast.view.orthographic=true;m.broadcast.view.farClipPlane=900;m.broadcast.Pose(Vector3.zero,new Vector3(0,28,-43),58,true);m.fit=m.broadcast.gameObject.AddComponent<SportsCameraFit>();m.fit.cameraTarget=m.broadcast.view;m.fit.arenaFit=true;m.fit.arenaBounds=new Bounds(new Vector3(-5,-1,0),new Vector3(73,9,24));m.fit.sideInset=.025f;m.fit.topInset=.09f;m.fit.bottomInset=.12f;m.fit.Apply();m.cameras=new[]{m.broadcast.view};m.atmosphere=SportsChaosAuthoring.Weather(m,Folder);m.atmosphere.sun.color=new Color(1,.63f,.35f);m.ruts=m.gameObject.AddComponent<TugRuts>();m.ruts.match=m;m.ruts.trails=new TrailRenderer[32];var rutMaterial=SportsEventAuthoring.Mat(Folder,"Wet pressed wheel grooves",new Color(.065f,.035f,.018f),.5f);for(int i=0;i<32;i++){var trail=new GameObject("Persistent NWH wheel rut "+i).AddComponent<TrailRenderer>();trail.sharedMaterial=rutMaterial;trail.time=120;trail.minVertexDistance=.12f;trail.startWidth=trail.endWidth=.17f;trail.emitting=false;trail.numCapVertices=2;trail.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;m.ruts.trails[i]=trail;}SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);Meters(m);SportsBroadcastAuthoring.ApplyScene();SportsEventAuthoring.Save(Folder);Validate();}
 static void Meters(TugMatch m){var hud=m.gameObject.AddComponent<TugHUD>();hud.match=m;var root=SportsUIAuthoring.Rect("Tug effort and edge broadcast meters",m.menus.hud.transform,new Vector2(1040,110),Vector2.zero);var rect=root.GetComponent<RectTransform>();rect.anchorMin=rect.anchorMax=new Vector2(.5f,0);rect.pivot=new Vector2(.5f,0);rect.anchoredPosition=new Vector2(100,78);root.AddComponent<UnityEngine.UI.Image>().color=new Color(.015f,.025f,.045f,.9f);root.AddComponent<SportsBroadcastPlate>();hud.root=root;hud.readout=SportsUIAuthoring.Text("Actual rope load and advantage",root.transform,"",new Vector2(980,28),new Vector2(0,37),23);hud.effort=new Michsky.UI.Heat.ProgressBar[2];hud.danger=new Michsky.UI.Heat.ProgressBar[2];hud.teamLabels=new TMPro.TMP_Text[2];var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Heat - Complete Modern UI/Prefabs/UI Elements/Progress Bar/Progress Bar.prefab");for(int team=0;team<2;team++){float x=team==0?-255:255;var color=team==0?new Color(.15f,.65f,1):new Color(1,.42f,.08f);hud.teamLabels[team]=SportsUIAuthoring.Text("Team effort and ledge safety "+team,root.transform,"",new Vector2(490,25),new Vector2(x,10),20);hud.teamLabels[team].color=color;for(int bar=0;bar<2;bar++){var instance=(GameObject)PrefabUtility.InstantiatePrefab(prefab,root.transform);instance.name=bar==0?"Heat team pulling effort":"Heat remaining ledge safety";var rt=instance.GetComponent<RectTransform>();rt.anchorMin=rt.anchorMax=rt.pivot=new Vector2(.5f,.5f);rt.anchoredPosition=new Vector2(x,bar==0?-13:-35);rt.sizeDelta=new Vector2(470,14);var meter=instance.GetComponentInChildren<Michsky.UI.Heat.ProgressBar>(true);meter.onValueChanged=new Michsky.UI.Heat.ProgressBar.OnValueChanged();meter.maxValue=100;meter.currentValue=0;meter.barImage.color=bar==0?color:new Color(.9f,.75f,.3f);foreach(var text in instance.GetComponentsInChildren<TMPro.TMP_Text>(true))text.gameObject.SetActive(false);meter.Initialize();meter.UpdateUI();if(bar==0)hud.effort[team]=meter;else hud.danger[team]=meter;}}}
 static Mesh Platform(){string path="Assets/"+Folder+"/Models/Beveled solid mountain ledge.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh{name="Modeled beveled volcanic ledge"};AssetDatabase.CreateAsset(mesh,path);}var outline=new[]{new Vector2(-15,-8),new Vector2(-9,-14),new Vector2(9,-14),new Vector2(15,-8),new Vector2(15,8),new Vector2(9,14),new Vector2(-9,14),new Vector2(-15,8)};var vertices=new List<Vector3>();foreach(var p in outline)vertices.Add(new Vector3(p.x,0,p.y));foreach(var p in outline)vertices.Add(new Vector3(p.x*.65f,-36,p.y*.65f));vertices.Add(Vector3.zero);vertices.Add(Vector3.down*36);var tris=new List<int>();for(int i=0;i<8;i++){int j=(i+1)%8;tris.AddRange(new[]{16,j,i,17,8+i,8+j,i,j,8+i,j,8+j,8+i});}mesh.Clear();mesh.vertices=vertices.ToArray();mesh.triangles=tris.ToArray();mesh.uv=vertices.Select(v=>new Vector2(v.x,v.z)*.1f).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);return mesh;}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<TugMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<TugMatch>();}if(m==null||m.trucks.Length!=8||m.headers.Length!=2||m.ropes.Length!=9||m.fragments.Any(f=>f.pieces.Length!=12)||m.replay.sources.Length!=8||m.ruts.trails.Length!=32||m.atmosphere==null)throw new Exception("Complete Tug scene references required");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One Tug listener required");Debug.Log("TUG_NATIVE_SCENE_VALIDATED");}
